  select '17d0dbfd-f565-5f15-963f-7fe90a1ed9a3', t.id from public.topics t join public.ejes e on e.id = t.eje_id
  where e.slug = 'algebra-y-funciones' and e.subject = 'm1' and t.slug = 'ecuaciones-inecuaciones-lineales'
  on conflict do nothing;
-- m1-algebra-y-funciones-014
insert into public.questions (id, external_key, content, alternatives, correct_answer, difficulty, explanation, subject, habilidad, is_active) values ('d0bff601-be52-5094-abbe-05856c69acbe', 'm1-algebra-y-funciones-014', 'Si $x + y = 11$ y $x - y = 3$, ¿cuál es el valor de $y$?', '[{"id":"A","content":"$3$"},{"id":"B","content":"$4$"},{"id":"C","content":"$7$"},{"id":"D","content":"$8$"},{"id":"E","content":"No sé responder esta pregunta"}]'::jsonb, 'B', 'easy'::difficulty_level, 'Idea clave: al sumar ambas ecuaciones se elimina $y$ y se obtiene $x$ de inmediato.
Paso 1: $(x + y) + (x - y) = 11 + 3$, así que $2x = 14$ y $x = 7$.
Paso 2: reemplazando en $x + y = 11$: $y = 4$.
Respuesta: B, $y = 4$.
Errores frecuentes: La A confunde $y$ con la diferencia $x - y$. La C corresponde al valor de $x$, no al de $y$. La D resulta de calcular $11 - 3$ y olvidar dividir por $2$.', 'm1', 'resolver_problemas', true)
  on conflict (id) do update set content = excluded.content, alternatives = excluded.alternatives, correct_answer = excluded.correct_answer, difficulty = excluded.difficulty, explanation = excluded.explanation, subject = excluded.subject, habilidad = excluded.habilidad, external_key = excluded.external_key;
