  select 'b0192e88-555b-5f84-a786-c620f35f51ab', t.id from public.topics t join public.ejes e on e.id = t.eje_id
  where e.slug = 'algebra-y-funciones' and e.subject = 'm1' and t.slug = 'ecuaciones-inecuaciones-lineales'
