-- m1-algebra-y-funciones-049
insert into public.questions (id, external_key, content, alternatives, correct_answer, difficulty, explanation, subject, habilidad, is_active) values ('b7177410-6aa8-5d23-bf5e-1e4e92ae7295', 'm1-algebra-y-funciones-049', 'Sofía, que vive en Osorno, abrió un saco nuevo de alimento para su perro. La cantidad de alimento que queda en el saco, en kilogramos, $d$ días después de abrirlo se modela con la función $A(d) = 15 - 0{,}4d$.

¿Qué representa el número $0{,}4$ en este modelo?', '[{"id":"A","content":"La cantidad de kilogramos de alimento que tenía el saco al abrirlo."},{"id":"B","content":"La cantidad de kilogramos de alimento que come el perro cada día."},{"id":"C","content":"La cantidad de días que dura el saco de alimento."},{"id":"D","content":"La cantidad de kilogramos de alimento que quedan en el saco después de $15$ días."},{"id":"E","content":"No sé responder esta pregunta"}]'::jsonb, 'B', 'easy'::difficulty_level, 'Idea clave: en una función afín, el número que multiplica a la variable es lo que cambia la cantidad por cada unidad de tiempo.
Paso 1: en $A(d) = 15 - 0{,}4d$ la pendiente es $-0{,}4$: cada día el alimento disminuye $0{,}4$ kg.
Paso 2: esa disminución diaria es lo que come el perro cada día.
Respuesta: B, la cantidad de kilogramos de alimento que come el perro cada día.
Errores frecuentes: La A corresponde al $15$, que es $A(0)$. La C confunde la pendiente con la duración del saco, que es $15 : 0{,}4 = 37{,}5$ días. La D confunde la pendiente con $A(15) = 15 - 6 = 9$ kg.', 'm1', 'modelar', true)
  on conflict (id) do update set content = excluded.content, alternatives = excluded.alternatives, correct_answer = excluded.correct_answer, difficulty = excluded.difficulty, explanation = excluded.explanation, subject = excluded.subject, habilidad = excluded.habilidad, external_key = excluded.external_key;
