  select 'b7177410-6aa8-5d23-bf5e-1e4e92ae7295', t.id from public.topics t join public.ejes e on e.id = t.eje_id
  where e.slug = 'algebra-y-funciones' and e.subject = 'm1' and t.slug = 'funcion-lineal-afin'
