-- m1-numeros-026
insert into public.questions (id, external_key, content, alternatives, correct_answer, difficulty, explanation, subject, habilidad, is_active) values ('9999ebcd-da58-5e7b-9321-7aefb11725db', 'm1-numeros-026', 'En una mina subterránea de la Región de O''Higgins, las posiciones bajo la superficie se representan con números negativos. Un ascensor de carga se encuentra en la posición $-120$ m, desciende $85$ m y luego asciende $140$ m.

¿En qué posición queda el ascensor?', '[{"id":"A","content":"$-65$ m"},{"id":"B","content":"$65$ m"},{"id":"C","content":"$105$ m"},{"id":"D","content":"$345$ m"},{"id":"E","content":"No sé responder esta pregunta"}]'::jsonb, 'A', 'easy'::difficulty_level, 'Idea clave: los descensos se restan y los ascensos se suman, partiendo desde la posición negativa inicial.
Paso 1: tras descender: $-120 - 85 = -205$.
Paso 2: tras ascender: $-205 + 140 = -65$.
Respuesta: A, el ascensor queda en $-65$ m, es decir, $65$ m bajo la superficie.
Errores frecuentes: La B tiene el valor correcto con el signo cambiado, como si quedara sobre la superficie. La C trata el descenso como ascenso: $-120 + 85 + 140 = 105$. La D suma todas las cantidades sin considerar los signos: $120 + 85 + 140 = 345$.', 'm1', 'resolver_problemas', true)
  on conflict (id) do update set content = excluded.content, alternatives = excluded.alternatives, correct_answer = excluded.correct_answer, difficulty = excluded.difficulty, explanation = excluded.explanation, subject = excluded.subject, habilidad = excluded.habilidad, external_key = excluded.external_key;
