  select '9999ebcd-da58-5e7b-9321-7aefb11725db', t.id from public.topics t join public.ejes e on e.id = t.eje_id
  where e.slug = 'numeros' and e.subject = 'm1' and t.slug = 'enteros-y-racionales'
