  select '0418a327-3ec8-5b3d-8446-532244d9cdaf', t.id from public.topics t join public.ejes e on e.id = t.eje_id
  where e.slug = 'numeros' and e.subject = 'm1' and t.slug = 'enteros-y-racionales'
