  select '2e74a9b1-6ec8-545e-a655-c6c9f0678c5e', t.id from public.topics t join public.ejes e on e.id = t.eje_id
  where e.slug = 'numeros' and e.subject = 'm1' and t.slug = 'porcentaje'
