insert into public.questions (id, external_key, content, alternatives, correct_answer, difficulty, explanation, subject, habilidad, is_active) values ('5f63491e-1cce-54b5-ba36-a1ab609afd29', 'm1-numeros-039', 'En una estación de servicio de Los Ángeles, el precio del litro de bencina pasó de $1\,250$ pesos a $1\,300$ pesos.

¿En qué porcentaje aumentó el precio del litro de bencina?', '[{"id":"A","content":"En aproximadamente un $3{,}8\\%$"},{"id":"B","content":"En un $4\\%$"},{"id":"C","content":"En un $50\\%$"},{"id":"D","content":"En un $104\\%$"},{"id":"E","content":"No sé responder esta pregunta"}]'::jsonb, 'B', 'medium'::difficulty_level, 'Idea clave: el aumento porcentual se calcula respecto del precio inicial.
Paso 1: el aumento fue de $1\,300 - 1\,250 = 50$ pesos.
Paso 2: $\frac{50}{1\,250} = 0{,}04$, es decir, un $4\%$.
Respuesta: B, el precio aumentó en un $4\%$.
Errores frecuentes: La A calcula el aumento respecto del precio final: $\frac{50}{1\,300} \approx 3{,}8\%$. La C confunde los $50$ pesos de aumento con el porcentaje. La D interpreta $\frac{1\,300}{1\,250} = 1{,}04$ como un aumento del $104\%$, cuando ese cociente indica que el precio nuevo es el $104\%$ del anterior.', 'm1', 'resolver_problemas', true)
  on conflict (id) do update set content = excluded.content, alternatives = excluded.alternatives, correct_answer = excluded.correct_answer, difficulty = excluded.difficulty, explanation = excluded.explanation, subject = excluded.subject, habilidad = excluded.habilidad, external_key = excluded.external_key;
