insert into public.questions (id, external_key, content, alternatives, correct_answer, difficulty, explanation, subject, habilidad, is_active) values ('a9d6c555-7d85-5954-9429-64b3ccce6e85', 'm1-probabilidad-y-estadistica-009', 'El promedio de estatura de las $12$ jugadoras de un equipo de vóleibol de Iquique es $1{,}80$ m. Se incorpora una nueva jugadora y el promedio de estatura de las $13$ jugadoras pasa a ser $1{,}81$ m.

¿Cuál es la estatura de la nueva jugadora?', '[{"id":"A","content":"$1{,}82$ m"},{"id":"B","content":"$1{,}92$ m"},{"id":"C","content":"$1{,}93$ m"},{"id":"D","content":"$1{,}94$ m"},{"id":"E","content":"No sé responder esta pregunta"}]'::jsonb, 'C', 'hard'::difficulty_level, 'Idea clave: a partir de cada promedio se obtiene la suma total de estaturas; la diferencia entre ambas sumas es la estatura de la nueva jugadora.
Paso 1: la suma de las $12$ estaturas es $12 \cdot 1{,}80 = 21{,}60$ m.
Paso 2: la suma de las $13$ estaturas es $13 \cdot 1{,}81 = 23{,}53$ m.
Paso 3: la nueva jugadora mide $23{,}53 - 21{,}60 = 1{,}93$ m. Otra forma: mide el nuevo promedio más $0{,}01$ m por cada una de las otras $12$, es decir, $1{,}81 + 0{,}12 = 1{,}93$ m.
Respuesta: C, $1{,}93$ m.
Errores frecuentes: La A solo suma $0{,}01$ al nuevo promedio. La B suma $0{,}12$ al promedio antiguo y no al nuevo. La D suma $13 \cdot 0{,}01$, contando también a la nueva jugadora.', 'm1', 'modelar', true)
  on conflict (id) do update set content = excluded.content, alternatives = excluded.alternatives, correct_answer = excluded.correct_answer, difficulty = excluded.difficulty, explanation = excluded.explanation, subject = excluded.subject, habilidad = excluded.habilidad, external_key = excluded.external_key;
