  select '25121286-4410-5c7f-8e5a-91244579df5e', t.id from public.topics t join public.ejes e on e.id = t.eje_id
  where e.slug = 'probabilidad-y-estadistica' and e.subject = 'm1' and t.slug = 'medidas-de-posicion'
