  select '09528726-c828-5a6e-b75e-38845f0be21e', t.id from public.topics t join public.ejes e on e.id = t.eje_id
  where e.slug = 'probabilidad-y-estadistica' and e.subject = 'm1' and t.slug = 'reglas-probabilidades'
  on conflict do nothing;
-- m1-probabilidad-y-estadistica-019
insert into public.questions (id, external_key, content, alternatives, correct_answer, difficulty, explanation, subject, habilidad, is_active) values ('5e76d050-a803-5ba2-ab72-821b3e8164f0', 'm1-probabilidad-y-estadistica-019', 'En un curso de $40$ estudiantes de Osorno, $22$ practican fútbol, $15$ practican básquetbol y $8$ practican ambos deportes. Si se elige al azar a un estudiante del curso, ¿cuál es la probabilidad de que practique al menos uno de estos dos deportes?', '[{"id":"A","content":"$\\dfrac{8}{40}$"},{"id":"B","content":"$\\dfrac{11}{40}$"},{"id":"C","content":"$\\dfrac{21}{40}$"},{"id":"D","content":"$\\dfrac{29}{40}$"},{"id":"E","content":"No sé responder esta pregunta"}]'::jsonb, 'D', 'medium'::difficulty_level, 'Idea clave: por la regla de la adición, $P(F \cup B) = P(F) + P(B) - P(F \cap B)$, para no contar dos veces a quienes practican ambos.
Paso 1: los que practican al menos uno son $22 + 15 - 8 = 29$ estudiantes.
Paso 2: la probabilidad es $\frac{29}{40}$.
Respuesta: D, $\frac{29}{40}$.
Errores frecuentes: La A es la probabilidad de practicar ambos deportes. La B es la probabilidad de no practicar ninguno ($40 - 29 = 11$ estudiantes). La C resta dos veces la intersección ($22 + 15 - 16 = 21$).', 'm1', 'modelar', true)
  on conflict (id) do update set content = excluded.content, alternatives = excluded.alternatives, correct_answer = excluded.correct_answer, difficulty = excluded.difficulty, explanation = excluded.explanation, subject = excluded.subject, habilidad = excluded.habilidad, external_key = excluded.external_key;
