  select '978b72f2-3c66-5b4a-bd34-7ba2dad7911c', t.id from public.topics t join public.ejes e on e.id = t.eje_id
  where e.slug = 'probabilidad-y-estadistica' and e.subject = 'm1' and t.slug = 'reglas-probabilidades'
