  select '5f1dab35-0123-5d42-8df6-81e8d5db50e0', t.id from public.topics t join public.ejes e on e.id = t.eje_id
  where e.slug = 'probabilidad-y-estadistica' and e.subject = 'm1' and t.slug = 'tablas-y-graficos'
