  select '1f5e16ad-f3cb-5ede-86d7-30d6e1194335', t.id from public.topics t join public.ejes e on e.id = t.eje_id
  where e.slug = 'probabilidad-y-estadistica' and e.subject = 'm1' and t.slug = 'tablas-y-graficos'
