  select '9d14a0df-283c-598a-9f91-13390e9caeef', t.id from public.topics t join public.ejes e on e.id = t.eje_id
  where e.slug = 'probabilidad-y-estadistica' and e.subject = 'm1' and t.slug = 'reglas-probabilidades'
