  select 'ba6422a6-a503-581a-b86a-5f652f3f00e1', t.id from public.topics t join public.ejes e on e.id = t.eje_id
  where e.slug = 'probabilidad-y-estadistica' and e.subject = 'm1' and t.slug = 'tablas-y-graficos'
