  select 'a6d936c9-224b-521c-bbe6-d3eef7f33307', t.id from public.topics t join public.ejes e on e.id = t.eje_id
  where e.slug = 'probabilidad-y-estadistica' and e.subject = 'm1' and t.slug = 'reglas-probabilidades'
