  select '6f05c1d8-0926-542a-9791-20a2ce30536f', t.id from public.topics t join public.ejes e on e.id = t.eje_id
  where e.slug = 'probabilidad-y-estadistica' and e.subject = 'm1' and t.slug = 'medidas-de-posicion'
