  where e.slug = 'algebra-y-funciones' and e.subject = 'm2' and t.slug = 'funcion-cuadratica'
  on conflict do nothing;
-- m2-algebra-y-funciones-103
insert into public.questions (id, external_key, content, alternatives, correct_answer, difficulty, explanation, subject, habilidad, is_active) values ('a0a39264-a7bf-50ef-929d-8197f7eaff67', 'm2-algebra-y-funciones-103', 'Considera la función $f(x)=ax^{2}+bx+c$, con dominio el conjunto de los números reales, donde $a$, $b$ y $c$ son números reales tales que $a<0$ y $c>0$.

¿Cuál de las siguientes afirmaciones es siempre verdadera?', '[{"id":"A","content":"La gráfica de $f$ no intersecta al eje X."},{"id":"B","content":"El vértice de la gráfica de $f$ está en el segundo cuadrante."},{"id":"C","content":"El valor mínimo de $f$ es $c$."},{"id":"D","content":"$f$ tiene dos ceros reales, uno positivo y otro negativo."},{"id":"E","content":"No sé responder esta pregunta"}]'::jsonb, 'D', 'hard'::difficulty_level, 'Idea clave: el signo de $ac$ determina el signo del discriminante y del producto de los ceros.
Paso 1: Como $a<0$ y $c>0$, $ac<0$, así que $-4ac>0$ y el discriminante $b^{2}-4ac$ es positivo: hay dos ceros reales distintos.
Paso 2: El producto de los ceros es $\frac{c}{a}<0$, por lo que tienen distinto signo.
Respuesta: D, $f$ tiene dos ceros reales, uno positivo y otro negativo.
Errores frecuentes: La A es falsa, porque el discriminante es positivo y la gráfica corta al eje X. La B depende de $b$: si $b>0$, la abscisa del vértice $-\frac{b}{2a}$ es positiva y el vértice queda en el primer cuadrante. La C es falsa: con $a<0$ la parábola abre hacia abajo y no tiene mínimo; $c$ es solo el valor $f(0)$.', 'm2', 'argumentar', true)
  on conflict (id) do update set content = excluded.content, alternatives = excluded.alternatives, correct_answer = excluded.correct_answer, difficulty = excluded.difficulty, explanation = excluded.explanation, subject = excluded.subject, habilidad = excluded.habilidad, external_key = excluded.external_key;
