  where e.slug = 'algebra-y-funciones' and e.subject = 'm2' and t.slug = 'funcion-lineal-afin'
  on conflict do nothing;
-- m2-algebra-y-funciones-139
insert into public.questions (id, external_key, content, alternatives, correct_answer, difficulty, explanation, subject, habilidad, is_active) values ('1032c44f-2a47-5e0b-a278-deac5eb27d86', 'm2-algebra-y-funciones-139', '¿Cuál de las siguientes expresiones es un factor de $x^{4}-13x^{2}+36$?', '[{"id":"A","content":"$x-6$"},{"id":"B","content":"$x-4$"},{"id":"C","content":"$x^{2}+4$"},{"id":"D","content":"$x+2$"},{"id":"E","content":"No sé responder esta pregunta"}]'::jsonb, 'D', 'medium'::difficulty_level, 'Idea clave: la expresión es cuadrática en $x^{2}$; con el cambio $u=x^{2}$ se factoriza y luego se aplica diferencia de cuadrados.
Paso 1: $u^{2}-13u+36=(u-4)(u-9)$.
Paso 2: $x^{4}-13x^{2}+36=(x^{2}-4)(x^{2}-9)=(x-2)(x+2)(x-3)(x+3)$, así que $x+2$ es un factor.
Respuesta: D, $x+2$.
Errores frecuentes: La A confunde la constante $36$ con un factor lineal $x-6$. La B confunde el factor $x^{2}-4$ con $x-4$. La C tiene un error de signo: $x^{2}+4$ no divide a la expresión.', 'm2', 'resolver_problemas', true)
  on conflict (id) do update set content = excluded.content, alternatives = excluded.alternatives, correct_answer = excluded.correct_answer, difficulty = excluded.difficulty, explanation = excluded.explanation, subject = excluded.subject, habilidad = excluded.habilidad, external_key = excluded.external_key;
