  select '7a277980-58e3-5a4b-9a52-1d008a7c3880', t.id from public.topics t join public.ejes e on e.id = t.eje_id
  where e.slug = 'algebra-y-funciones' and e.subject = 'm2' and t.slug = 'funcion-lineal-afin'
