  select '788074ff-0d00-5cbc-8294-3896ff103c86', t.id from public.topics t join public.ejes e on e.id = t.eje_id
  where e.slug = 'algebra-y-funciones' and e.subject = 'm2' and t.slug = 'expresiones-algebraicas'
