  select '1eb3431d-e643-552a-85ec-99c2bc2f031a', t.id from public.topics t join public.ejes e on e.id = t.eje_id
  where e.slug = 'algebra-y-funciones' and e.subject = 'm2' and t.slug = 'funcion-cuadratica'
