  select 'b878d151-cd1a-54c3-96e3-4f10b2353293', t.id from public.topics t join public.ejes e on e.id = t.eje_id
  where e.slug = 'algebra-y-funciones' and e.subject = 'm2' and t.slug = 'expresiones-algebraicas'
