  select '8c5fb531-28ad-5ef8-81a0-f8011a12520b', t.id from public.topics t join public.ejes e on e.id = t.eje_id
  where e.slug = 'algebra-y-funciones' and e.subject = 'm2' and t.slug = 'sistemas-2x2'
