  select '0a9fae33-555f-57e2-8e9a-37f0fefbd568', t.id from public.topics t join public.ejes e on e.id = t.eje_id
  where e.slug = 'algebra-y-funciones' and e.subject = 'm2' and t.slug = 'funciones-trigonometricas'
