  select 'aea94824-0e5c-5ec3-bfd0-4f0d1b1cf9fe', t.id from public.topics t join public.ejes e on e.id = t.eje_id
  where e.slug = 'geometria' and e.subject = 'm2' and t.slug = 'transformaciones-isometricas'
