  select '573d93ea-3d91-53b9-a59c-8fa163ba9bca', t.id from public.topics t join public.ejes e on e.id = t.eje_id
  where e.slug = 'geometria' and e.subject = 'm2' and t.slug = 'figuras-geometricas'
