  select '44a67a70-9ae3-5c1f-b82e-790f308ab8a8', t.id from public.topics t join public.ejes e on e.id = t.eje_id
  where e.slug = 'geometria' and e.subject = 'm2' and t.slug = 'figuras-geometricas'
