  select '8f30c8f6-3689-5bc1-9183-ece7cd421a16', t.id from public.topics t join public.ejes e on e.id = t.eje_id
  where e.slug = 'geometria' and e.subject = 'm2' and t.slug = 'transformaciones-isometricas'
