  select 'f4fc279f-ed80-513b-ac0e-e7ed475aadcf', t.id from public.topics t join public.ejes e on e.id = t.eje_id
  where e.slug = 'geometria' and e.subject = 'm2' and t.slug = 'transformaciones-isometricas'
