insert into public.questions (id, external_key, content, alternatives, correct_answer, difficulty, explanation, subject, habilidad, is_active) values ('f7f09528-838e-540d-a32f-dda0ecf681a5', 'm2-numeros-118', 'Sea $n$ un número entero.

¿Cuál es el valor de la expresión $\dfrac{4^{n+1}-2^{2n-1}}{2^{2n+1}}$?', '[{"id":"A","content":"$\\dfrac{3}{2}$"},{"id":"B","content":"$\\dfrac{7}{4}$"},{"id":"C","content":"$\\dfrac{15}{8}$"},{"id":"D","content":"$\\dfrac{7}{2}$"},{"id":"E","content":"No sé responder esta pregunta"}]'::jsonb, 'B', 'hard'::difficulty_level, 'Idea clave: se escribe todo en base $2$ y se factoriza la potencia menor del numerador.
Paso 1: $4^{n+1}=2^{2n+2}$.
Paso 2: el numerador es $2^{2n+2}-2^{2n-1}=2^{2n-1}\left(2^{3}-1\right)=7\cdot2^{2n-1}$.
Paso 3: $\dfrac{7\cdot2^{2n-1}}{2^{2n+1}}=7\cdot2^{-2}=\dfrac{7}{4}$, que no depende de $n$.
Respuesta: B, $\dfrac{7}{4}$.
Errores frecuentes: La A toma $2^{2n-1}$ como si fuera $4^{n}$. La C lo toma como $2^{2n-2}$. La D divide por $2^{2n}$ en lugar de $2^{2n+1}$.', 'm2', 'resolver_problemas', true)
  on conflict (id) do update set content = excluded.content, alternatives = excluded.alternatives, correct_answer = excluded.correct_answer, difficulty = excluded.difficulty, explanation = excluded.explanation, subject = excluded.subject, habilidad = excluded.habilidad, external_key = excluded.external_key;
