  select 'e193bcb2-25a6-568f-9bea-69c0eead298d', t.id from public.topics t join public.ejes e on e.id = t.eje_id
  where e.slug = 'probabilidad-y-estadistica' and e.subject = 'm2' and t.slug = 'probabilidad-condicional'
