  select 'c4dcdbd1-9136-5cce-ae09-d433f6f85c29', t.id from public.topics t join public.ejes e on e.id = t.eje_id
  where e.slug = 'probabilidad-y-estadistica' and e.subject = 'm2' and t.slug = 'medidas-de-dispersion'
