  select 'cd531011-f4b5-5f0c-bb6a-364d0adb7fd1', t.id from public.topics t join public.ejes e on e.id = t.eje_id
  where e.slug = 'probabilidad-y-estadistica' and e.subject = 'm2' and t.slug = 'reglas-probabilidades'
