  select 'aa60f00a-0928-52fd-ac9a-beb4f0ff74ac', t.id from public.topics t join public.ejes e on e.id = t.eje_id
  where e.slug = 'probabilidad-y-estadistica' and e.subject = 'm2' and t.slug = 'reglas-probabilidades'
