  select 'c9070aa8-f877-5521-884a-e9cddeb3926a', t.id from public.topics t join public.ejes e on e.id = t.eje_id
  where e.slug = 'probabilidad-y-estadistica' and e.subject = 'm2' and t.slug = 'probabilidad-condicional'
