  select 'acec1bc0-efeb-5f4f-be5b-e65d84ad6cee', t.id from public.topics t join public.ejes e on e.id = t.eje_id
  where e.slug = 'probabilidad-y-estadistica' and e.subject = 'm2' and t.slug = 'tablas-y-graficos'
