  select '778011d5-aa2e-54ba-b0e3-e9c8a9532519', t.id from public.topics t join public.ejes e on e.id = t.eje_id
  where e.slug = 'probabilidad-y-estadistica' and e.subject = 'm2' and t.slug = 'medidas-de-dispersion'
