  select '6f877e08-d065-58c9-8321-398745ef47f1', t.id from public.topics t join public.ejes e on e.id = t.eje_id
  where e.slug = 'probabilidad-y-estadistica' and e.subject = 'm2' and t.slug = 'medidas-de-posicion'
