  select '900aab45-0d21-5dd8-8a48-7001c9def614', t.id from public.topics t join public.ejes e on e.id = t.eje_id
  where e.slug = 'probabilidad-y-estadistica' and e.subject = 'm2' and t.slug = 'tablas-y-graficos'
