  select '944a99ef-8b76-5a83-9d36-b207ec63f8fe', t.id from public.topics t join public.ejes e on e.id = t.eje_id
  where e.slug = 'probabilidad-y-estadistica' and e.subject = 'm2' and t.slug = 'permutacion-combinatoria'
