  select 'b7d91ba5-77fb-53f6-8176-0e1e181b4e99', t.id from public.topics t join public.ejes e on e.id = t.eje_id
  where e.slug = 'probabilidad-y-estadistica' and e.subject = 'm2' and t.slug = 'permutacion-combinatoria'
