  select '6ffebe38-e1aa-5f64-b504-051c6053de1d', t.id from public.topics t join public.ejes e on e.id = t.eje_id
  where e.slug = 'probabilidad-y-estadistica' and e.subject = 'm2' and t.slug = 'modelos-probabilisticos'
